# Dotstory content update - applies the new written content + the Services page.
# Put this file in your site folder (the one that contains index.html and the _nuxt folder), then run:
#   powershell -ExecutionPolicy Bypass -File .\apply-dotstory-update.ps1
# Optional: add -Push to also commit and push to git afterwards.
param([switch]$Push)
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
if (-not (Test-Path (Join-Path $root 'index.html')) -or -not (Test-Path (Join-Path $root '_nuxt'))) {
  Write-Host "Run this from your site folder (it must contain index.html and the _nuxt folder)." -ForegroundColor Red
  exit 1
}
$backup = Join-Path $root ('_backup_before_content_update_' + (Get-Date -Format 'yyyyMMdd_HHmmss'))
$files = @(
  @{ Path='index.html'; Sha='6db376ba02b4efad69f89a8d8dd8e65b0807a010954032fdefd8f6a7a38c139b'; Data='' }
  @{ Path='about'; Sha='b3397e2c1e72dae4badd98097a22a37734eb0514ecc065c4c521d27206f4aee0'; Data='' }
  @{ Path='services'; Sha='495c1abc75cbb9e948243a622d0a285fd6086ceb47f1e688fb49b5496dc4f30c'; Data='' }
  @{ Path='contact'; Sha='4c00770d44de37447f3193dff1bd4527078756ee9260bc817cf7a1b482441091'; Data='' }
  @{ Path='legal'; Sha='fcd294b409e4b96893f38ae751e740c9939d32322fd0f0db15f0d9925569b13c'; Data='' }
  @{ Path='vercel.json'; Sha='f2babc26f3a9e9f18e4858831ec8cd8ce1999dfa2623c206001e33472fb2d72b'; Data='H4sIAB4852oC/32PwQ6CMBBE73xF05MmKlej8eQn6M1wWMsojbWYdiEY4d8tjYDx4GXTzJud6b4SISQ70kbb68GQL+RGXMh4LHrikGsHxT6opyAI8YozIF9WTiHoMtU2R7Mq+G7kYsA5PGtLrEsbPRN5wN3JwvLQFEEXZhY7C1AO979xRuey4tbD1VrBt6q0TIpbgyuZ+dT1m/WdFw03PPvAfdgPP1oenw+M29FQk6liJ6PhtL9xK1RBzoN3FV+Wazm6u88rmw5KuuQNjSpDi2IBAAA=' }
  @{ Path='_nuxt/DC_P54Ec.js'; Sha='cb9a9f5c035b35c634bdaea2e196d5d164508788a9c3761fa87ba1b22f2a90f3'; Data='' }
  @{ Path='_nuxt/BAugoq4T.js'; Sha='b34c4f54816f30813c0940ad6495d9e017d7643d936567de8c94de21495de488'; Data='' }
  @{ Path='_nuxt/CPjIKiRm.js'; Sha='b5e34941fa3effd6d678297af8988dc54483ffb6011f1dcaa5b58cb348838d91'; Data='' }
)
function Unpack($b64) {
  $ms = New-Object System.IO.MemoryStream(,[Convert]::FromBase64String($b64))
  $gz = New-Object System.IO.Compression.GZipStream($ms, [System.IO.Compression.CompressionMode]::Decompress)
  $out = New-Object System.IO.MemoryStream
  $gz.CopyTo($out); $gz.Dispose()
  return ,$out.ToArray()
}
foreach ($f in $files) {
  $dest = Join-Path $root ($f.Path -replace '/', [IO.Path]::DirectorySeparatorChar)
  $bytes = Unpack $f.Data
  $sha = [BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash($bytes)).Replace('-','').ToLower()
  if ($sha -ne $f.Sha) { throw "Checksum mismatch for $($f.Path) - the script file may be damaged. Please download it again." }
  if (Test-Path $dest) {
    $bk = Join-Path $backup ($f.Path -replace '/', [IO.Path]::DirectorySeparatorChar)
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $bk) | Out-Null
    Copy-Item $dest $bk -Force
  }
  New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest) | Out-Null
  [IO.File]::WriteAllBytes($dest, $bytes)
  Write-Host ("  updated  " + $f.Path)
}
Write-Host ""
Write-Host "Done. $($files.Count) files written. Old versions are saved in: $backup" -ForegroundColor Green
if ($Push) {
  Push-Location $root
  git add -A -- . ':!_backup_before_content_update_*'
  git commit -m "Update site content to Dotstory copy and add Services page"
  git push
  Pop-Location
} else {
  Write-Host "Next: commit and push (or run again with -Push), and Vercel will redeploy."
}
